const html =  $input.first().json.data || '';

const baseUrl = 'https://www.uni-leipzig.de';

function decodeHtml(str = '') {
  return str
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&bdquo;/gi, '„')
    .replace(/&ldquo;/gi, '“')
    .replace(/&rdquo;/gi, '”')
    .replace(/&ndash;/gi, '–')
    .replace(/&mdash;/gi, '—')
    .replace(/&hellip;/gi, '…')
    .replace(/&#8729;/gi, '·')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<em>([\s\S]*?)<\/em>/gi, '$1')
    .replace(/<strong>([\s\S]*?)<\/strong>/gi, '$1')
    .replace(/<span\b[^>]*class=["'][^"']*\bhidden\b[^"']*["'][^>]*>[\s\S]*?<\/span>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function makeAbsoluteUrl(url = '') {
  if (!url) return '';
  if (url === '#') return '';
  if (/^https?:\/\//i.test(url)) return url;
  if (url.startsWith('/')) return baseUrl + url;
  return baseUrl + '/' + url;
}

function extractMainContent(str) {
  const start = str.search(/<main\b[^>]*id=["']content["'][^>]*>/i);
  if (start === -1) return str;
  const after = str.slice(start);
  const endRel = after.search(/<\/main>/i);
  return endRel === -1 ? after : after.slice(0, endRel + 7);
}

function findMatchingDivEnd(str, openStart) {
  const tagRegex = /<\/?div\b[^>]*>/gi;
  tagRegex.lastIndex = openStart;
  let depth = 0;
  let m;

  while ((m = tagRegex.exec(str)) !== null) {
    const tag = m[0];
    const isClosing = /^<\/div/i.test(tag);

    if (!isClosing) {
      depth += 1;
    } else {
      depth -= 1;
      if (depth === 0) {
        return tagRegex.lastIndex;
      }
    }
  }

  return -1;
}

function extractDivAt(str, startIndex) {
  const endIndex = findMatchingDivEnd(str, startIndex);
  if (endIndex === -1) return '';
  return str.slice(startIndex, endIndex);
}

function getAttr(tag, name) {
  const m = tag.match(new RegExp(`${name}=["']([^"']+)["']`, 'i'));
  return m ? m[1] : '';
}

function getSectionBlocks(mainHtml) {
  const sections = [];
  const sectionRegex = /<section\b[^>]*class=["'][^"']*\btx_mksearch\b[^"']*["'][^>]*>/gi;
  let match;

  while ((match = sectionRegex.exec(mainHtml)) !== null) {
    const sectionStart = match.index;
    const after = mainHtml.slice(sectionStart);
    const endRel = after.search(/<\/section>/i);
    if (endRel === -1) continue;

    const sectionHtml = after.slice(0, endRel + 10);

    const catMatch = sectionHtml.match(
      /<div\b[^>]*class=["'][^"']*\bcontentsection\b[^"']*["'][^>]*data-name=["']([^"']+)["'][^>]*>/i
    );
    if (!catMatch) continue;

    const category = decodeHtml(catMatch[1]);

    const resultsOpenMatch = sectionHtml.match(
      /<div\b[^>]*class=["'][^"']*\bresults\b[^"']*["'][^>]*>/i
    );
    if (!resultsOpenMatch) continue;

    const resultsOpenIndex = sectionHtml.search(
      /<div\b[^>]*class=["'][^"']*\bresults\b[^"']*["'][^>]*>/i
    );
    if (resultsOpenIndex === -1) continue;

    const resultsHtml = extractDivAt(sectionHtml, resultsOpenIndex);

    sections.push({
      kategorie: category,
      html: resultsHtml
    });
  }

  return sections;
}

function getAllTopLevelBlocksByClass(containerHtml, className) {
  const blocks = [];
  const openRegex = new RegExp(
    `<div\\b[^>]*class=["'][^"']*\\b${className}\\b[^"']*["'][^>]*>`,
    'gi'
  );

  let match;
  while ((match = openRegex.exec(containerHtml)) !== null) {
    const start = match.index;
    const block = extractDivAt(containerHtml, start);
    if (block) {
      blocks.push(block);
      openRegex.lastIndex = start + block.length;
    }
  }

  return blocks;
}

function parsePagesNewsDocs(category, resultsHtml) {
  const blocks = getAllTopLevelBlocksByClass(resultsHtml, 'searchresult');
  const out = [];

  for (const block of blocks) {
    const titleMatch = block.match(/<h3\b[^>]*>([\s\S]*?)<\/h3>/i);
    const titel = decodeHtml(titleMatch ? titleMatch[1] : '');

    const pMatches = [...block.matchAll(/<p\b[^>]*>([\s\S]*?)<\/p>/gi)]
      .map(m => decodeHtml(m[1]))
      .filter(Boolean);

    const inhalt = pMatches.join(' ').replace(/\s+/g, ' ').trim();

    const links = [...block.matchAll(/<a\b[^>]*href=["']([^"']+)["'][^>]*>/gi)]
      .map(m => m[1])
      .map(makeAbsoluteUrl)
      .filter(Boolean);

    // Für "Seiten" nicht den Breadcrumb-Link "/" nehmen, sondern bevorzugt readon/filelink/etc.
    let link = '';
    if (/Seiten|Nachrichten|Dokumente/i.test(category)) {
      const preferred = block.match(
        /<a\b[^>]*class=["'][^"']*\b(readon|filelink)\b[^"']*["'][^>]*href=["']([^"']+)["'][^>]*>/i
      );
      if (preferred) {
        link = makeAbsoluteUrl(preferred[2]);
      }
    }
    if (!link && links.length) {
      link = links[links.length - 1];
    }

    if (titel || link || inhalt) {
      out.push({ kategorie: category, titel, link, inhalt });
    }
  }

  return out;
}

function parseContacts(category, resultsHtml) {
  const blocks = getAllTopLevelBlocksByClass(resultsHtml, 'contactTeaser');
  const out = [];

  for (const block of blocks) {
    const titleMatch = block.match(/<h3\b[^>]*>([\s\S]*?)<\/h3>/i);
    const titel = decodeHtml(titleMatch ? titleMatch[1] : '');

    const descMatch = block.match(/<span\b[^>]*class=["'][^"']*\bdescription\b[^"']*["'][^>]*>([\s\S]*?)<\/span>/i);
    const desc = decodeHtml(descMatch ? descMatch[1] : '');

    const orgMatch = block.match(/<span\b[^>]*class=["'][^"']*\borg\b[^"']*["'][^>]*>([\s\S]*?)<\/span>/i);
    const org = decodeHtml(orgMatch ? orgMatch[1] : '');

    const addressMatch = block.match(/<p\b[^>]*class=["'][^"']*\baddress\b[^"']*["'][^>]*>([\s\S]*?)<\/p>/i);
    const address = decodeHtml(addressMatch ? addressMatch[1] : '');

    const telMatch = block.match(/Telefon:\s*[\s\S]*?<span\b[^>]*class=["'][^"']*\bvalue\b[^"']*["'][^>]*>([\s\S]*?)<\/span>/i);
    const tel = decodeHtml(telMatch ? telMatch[1] : '');

    const profileMatch = block.match(/<a\b[^>]*href=["']([^"']*\/personenprofil[^"']*)["'][^>]*>[\s\S]*?Zum Profil[\s\S]*?<\/a>/i);
    const websiteMatch = block.match(/<a\b[^>]*href=["']([^"']+)["'][^>]*>[\s\S]*?Webseite[\s\S]*?<\/a>/i);

    let link = '';
    if (profileMatch) link = makeAbsoluteUrl(profileMatch[1]);
    else if (websiteMatch) link = makeAbsoluteUrl(websiteMatch[1]);

    const inhalt = [desc, org, address, tel].filter(Boolean).join(' | ');

    if (titel || link || inhalt) {
      out.push({ kategorie: category, titel, link, inhalt });
    }
  }

  return out;
}

function parseEstablishments(category, resultsHtml) {
  const blocks = getAllTopLevelBlocksByClass(resultsHtml, 'contactTeaser');
  const out = [];

  for (const block of blocks) {
    const titleMatch = block.match(/<h3\b[^>]*>([\s\S]*?)<\/h3>/i);
    const titel = decodeHtml(titleMatch ? titleMatch[1] : '');

    const addressMatch = block.match(/<p\b[^>]*class=["'][^"']*\baddress\b[^"']*["'][^>]*>([\s\S]*?)<\/p>/i);
    const address = decodeHtml(addressMatch ? addressMatch[1] : '');

    const telMatch = block.match(/Telefon:\s*[\s\S]*?<span\b[^>]*class=["'][^"']*\bvalue\b[^"']*["'][^>]*>([\s\S]*?)<\/span>/i);
    const tel = decodeHtml(telMatch ? telMatch[1] : '');

    const websiteMatch = block.match(/<a\b[^>]*href=["']([^"']+)["'][^>]*>[\s\S]*?Webseite[\s\S]*?<\/a>/i);
    const link = websiteMatch ? makeAbsoluteUrl(websiteMatch[1]) : '';

    const inhalt = [address, tel].filter(Boolean).join(' | ');

    if (titel || link || inhalt) {
      out.push({ kategorie: category, titel, link, inhalt });
    }
  }

  return out;
}

const mainHtml = extractMainContent(html);
const sectionBlocks = getSectionBlocks(mainHtml);

let results = [];

for (const section of sectionBlocks) {
  const k = section.kategorie;

  if (/Kontakte/i.test(k)) {
    results.push(...parseContacts(k, section.html));
  } else if (/Einrichtung|Einrichtungen/i.test(k)) {
    results.push(...parseEstablishments(k, section.html));
  } else {
    results.push(...parsePagesNewsDocs(k, section.html));
  }
}

results = results.filter(r => r.titel || r.link || r.inhalt);

const seen = new Set();
results = results.filter(r => {
  const key = `${r.kategorie}|${r.titel}|${r.link}|${r.inhalt}`;
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

return [
  {
    json: {
      query: $('When Executed by Another Workflow').first().json.query || '',
      resultCount: results.length,
      results
    }
  }
];

const query =  $input.first().json.query || '';
const results = $input.first().json.results || [];

const searchContext = results
  .map((r, i) => {
    return [
      `Treffer ${i + 1}`,
      `Kategorie: ${r.kategorie || ''}`,
      `Titel: ${r.titel || ''}`,
      `Link: ${r.link || ''}`,
      `Inhalt: ${r.inhalt || ''}`
    ].join('\n');
  })
  .join('\n\n---\n\n');

return [
  {
    json: {
      query,
      resultCount: results.length,
      searchContext
    }
  }
];
